const raw = $input.first().json;
const msg = raw.message || {};
const adminId = String($env.ADMIN_TELEGRAM_ID || '0');
const senderId = String(msg.from?.id || '');
const chatId = String(msg.chat?.id || '');
const firstName = msg.from?.first_name || 'cliente';
let text = String(msg.text || msg.caption || '').trim();
let hadVoice = false;

const fileId = msg.voice?.file_id || msg.audio?.file_id || msg.video_note?.file_id || null;
const tgToken = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const openaiKey = String($env.OPENAI_API_KEY || '').trim();

if (!text && fileId && tgToken && openaiKey) {
  try {
    hadVoice = true;
    const meta = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.telegram.org/bot${tgToken}/getFile`,
      qs: { file_id: fileId },
      json: true,
    });
    const filePath = meta?.result?.file_path;
    if (!filePath) throw new Error('file_path vazio');
    const audio = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.telegram.org/file/bot${tgToken}/${filePath}`,
      encoding: 'arraybuffer',
      returnFullResponse: true,
    });
    const buf = Buffer.from(audio.body || audio);
    const FormData = require('form-data');
    const form = new FormData();
    form.append('file', buf, { filename: 'voice.ogg', contentType: 'audio/ogg' });
    form.append('model', 'whisper-1');
    form.append('language', 'pt');
    const tr = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/audio/transcriptions',
      headers: Object.assign({ Authorization: 'Bearer ' + openaiKey }, form.getHeaders()),
      body: form,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (tr.statusCode >= 200 && tr.statusCode < 300) {
      text = String(tr.body?.text || '').trim();
    } else {
      text = '';
    }
  } catch (e) {
    text = '';
    hadVoice = true;
  }
}

if (!text && hadVoice) {
  text = '[áudio recebido, mas não consegui transcrever]';
}
if (!text) text = '[mensagem sem texto]';

return [{ json: { adminId, senderId, chatId, firstName, text, hadVoice, message: msg } }];

const text = String($json.text || '').trim();
let intent = 'chat';

const wantsFinance = (/lan[cç]ar|despesa|gasto|paguei|recebi|comprei|contas?\s+para\s+pagar|lan[cç]amento/i.test(text)
  && /(r\$\s*\d+|\d+[.,]\d{2}|\b\d{1,6}\b)/i.test(text))
  || (/r\$\s*\d+/i.test(text) && /despesa|gasto|receita|pagar|lan[cç]ar/i.test(text));

const wantsCode = /(?:gerar|criar|gera|crie|faz(?:er)?)\s+(?:um\s+)?c[oó]digo/i.test(text)
  || /\bc[oó]digo\s+(?:de\s+)?(?:registro|convite|manual|ativa)/i.test(text)
  || /\bKING-[A-Z0-9]{2,30}\b/i.test(text);

const wantsDiag = /\b(diagn[oó]stico|health|status\s+do\s+site|site\s+caiu|\/status)\b/i.test(text)
  || /^(status|diagn[oó]stico)$/i.test(text);

if (wantsFinance) intent = 'finance';
else if (wantsCode) intent = 'code';
else if (wantsDiag) intent = 'diag';

let amount = null;
const am = text.match(/r\$\s*(\d+[.,]?\d*)/i) || text.match(/(\d+[.,]\d{2})/);
if (am) amount = parseFloat(String(am[1]).replace(',', '.'));
else if (wantsFinance) {
  const n = text.match(/\b(\d{1,6})\b/);
  if (n) amount = parseFloat(n[1]);
}

let type = /receita|recebi|entrou|ganhei/i.test(text) ? 'INCOME' : 'EXPENSE';
let status = /paguei|pago|j[aá]\s*paguei/i.test(text) ? 'PAID' : 'PENDING';
let description = text.replace(/r\$\s*\d+[.,]?\d*/ig, '').replace(/\s+/g, ' ').trim().slice(0, 180) || 'Lançamento via Telegram';

let customCode = '';
const cm = text.match(/\b(KING-[A-Z0-9]{2,30})\b/i)
  || text.match(/(?:gerar|criar|gera|crie)\s+c[oó]digo\s+([A-Z0-9][-_A-Z0-9]{2,30})/i);
if (cm) customCode = String(cm[1]).replace(/\s+/g, '').toUpperCase().slice(0, 32);

const today = new Date().toISOString().slice(0, 10);
return [{ json: { ...$json, intent, amount, type, status, description, customCode, transactionDate: today } }];

const prev = $input.first().json;
const base = String($env.CK_BASE_URL || 'https://www.conectaking.com.br').replace(/\/$/, '');
const token = String($env.CK_AGENT_JWT || '').trim();
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const intent = prev.intent;
const chatId = String(prev.chatId || '');

const KB = `CONHECIMENTO CONECTA KING:\n- Cartão/perfil digital + NFC (pulseira/tag). Sem app. Tag pública: https://tag.conectaking.com.br/{slug}\n- Site: https://www.conectaking.com.br | Login: /login | Registro: /registro (exige código de convite) | Senha: /recuperar-senha\n- Entrega: cartão virtual editável, Gestão Financeira, King Forms, King Selection (galeria de fotos), Bíblia, King Docs, recibos/orçamentos, PIX no cartão\n- Planos ref. (podem mudar no admin; confirme no site): Start 70/700, Prime 100/1000, Essential 150/1500, Finance 170/1700, Finance Plus 200/2000, Premium Plus 220/2200, Corporate 230/2300 (mensal/anual). Anual ~-20%, PIX ~-5%.\n- Código de REGISTRO/CONVITE: admin gera; cliente usa em /registro.\n- Código de PULSEIRA/NFC: só admin configura no usuário.\n- Instagram: https://www.instagram.com/conectaking`;

async function http(method, url, body, headers) {
  const opts = { method, url, headers: Object.assign({ Accept: 'application/json', 'Content-Type': 'application/json' }, headers || {}), json: true, returnFullResponse: true, ignoreHttpStatusErrors: true };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}
async function ck(method, path, body) {
  return http.call(this, method, base + path, body, token ? { Authorization: 'Bearer ' + token } : {});
}

function memory() {
  const store = $getWorkflowStaticData('global');
  if (!store.chats) store.chats = {};
  if (!store.chats[chatId]) store.chats[chatId] = [];
  return store.chats[chatId];
}
function pushMem(role, content) {
  const m = memory();
  m.push({ role, content: String(content || '').slice(0, 1500) });
  while (m.length > 12) m.shift();
}

async function openaiChat(system, userText) {
  if (!openaiKey) return null;
  pushMem('user', userText);
  const history = memory().slice(-10);
  const r = await http.call(this, 'POST', 'https://api.openai.com/v1/chat/completions', {
    model,
    temperature: 0.35,
    max_tokens: 700,
    messages: [{ role: 'system', content: system }, ...history],
  }, { Authorization: 'Bearer ' + openaiKey });
  if (!(r.statusCode >= 200 && r.statusCode < 300)) {
    return 'OpenAI erro (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 220);
  }
  const out = String(r.body?.choices?.[0]?.message?.content || '').trim();
  if (out) pushMem('assistant', out);
  return out;
}

const ADMIN_SYSTEM = `Você é o Assistente Executivo do Conecta King (Telegram) do Adriano King.\nFale PT-BR, direto, profissional. Use o conhecimento abaixo.\n\n${KB}\n\nIMPORTANTE:\n- Perguntas sobre o produto/preços/módulos = RESPONDA com o conhecimento. NÃO gere código.\n- Só execute ações quando o sistema já confirmou (você verá resultado em outras rotas).\n- Para o admin executar ações, oriente formatos EXATOS:\n  • lançar despesa R$ 100 contas de luz\n  • gerar código KING-NOME\n  • status  (ou diagnóstico)\n- Nunca invente que criou código/lançamento sem confirmação.\n- Se a mensagem for só dúvida, responda a dúvida.`;

let msg = '';
try {
  if (intent === 'diag') {
    const h = await ck.call(this, 'GET', '/health');
    msg = 'Diagnóstico Conecta King\nHTTP ' + h.statusCode + '\n' + JSON.stringify(h.body).slice(0, 400);
    pushMem('user', prev.text); pushMem('assistant', msg);
  } else if (intent === 'finance') {
    if (!token) msg = 'CK_AGENT_JWT não configurado.';
    else if (!prev.amount || !(prev.amount > 0)) msg = 'Não entendi o valor. Ex.: "lançar despesa R$ 100 contas para pagar"';
    else {
      const body = { type: prev.type || 'EXPENSE', amount: Number(prev.amount), description: prev.description || 'Lançamento via Telegram', transaction_date: prev.transactionDate, status: prev.status || 'PENDING' };
      const r = await ck.call(this, 'POST', '/api/finance/transactions', body);
      if (r.statusCode >= 200 && r.statusCode < 300) {
        const row = (r.body && r.body.data) || {};
        msg = 'Lançamento criado.\n' + (body.type === 'INCOME' ? 'Receita' : 'Despesa') + ': R$ ' + body.amount.toFixed(2) + '\nStatus: ' + body.status + '\nDesc: ' + body.description + (row.id ? '\nID: ' + row.id : '');
      } else msg = 'Falha ao lançar (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300);
    }
    pushMem('user', prev.text); pushMem('assistant', msg);
  } else if (intent === 'code') {
    if (!token) msg = 'CK_AGENT_JWT não configurado.';
    else if (!prev.customCode) msg = 'Para criar código, diga: gerar código KING-NOME (com hífen).';
    else {
      const r = await ck.call(this, 'POST', '/api/admin/codes/generate-manual', { customCode: prev.customCode, expiresAt: null });
      if (r.statusCode >= 200 && r.statusCode < 300) msg = 'Código criado: ' + prev.customCode;
      else msg = 'Falha ao criar código (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300);
    }
    pushMem('user', prev.text); pushMem('assistant', msg);
  } else {
    const prefix = prev.hadVoice ? '[transcrito de áudio] ' : '';
    msg = await openaiChat.call(this, ADMIN_SYSTEM, prefix + (prev.text || '')) || 'Sem OPENAI_API_KEY. Use: status | lançar despesa R$ X ... | gerar código KING-XXXX';
  }
} catch (e) {
  msg = 'Erro: ' + String(e.message || e).slice(0, 300);
}

return [{ json: { ...prev, outMessage: msg } }];

const prev = $input.first().json;
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const name = prev.firstName || 'olá';
const text = String(prev.text || '').trim();
const chatId = String(prev.chatId || '');

const KB = `CONHECIMENTO CONECTA KING:\n- Cartão/perfil digital + NFC. Sem app. Tag: https://tag.conectaking.com.br/{slug}\n- Site: https://www.conectaking.com.br | Login /login | Registro /registro (precisa código) | Senha /recuperar-senha\n- Entrega: cartão virtual, finanças, formulários, King Selection, Bíblia, docs, PIX\n- Planos ref.: Start 70, Prime 100, Essential 150, Finance 170, Finance Plus 200, Premium Plus 220, Corporate 230 (mensal; anual ~-20%). Confirme no site.\n- Código de acesso: só o King/admin libera.`;

function memory() {
  const store = $getWorkflowStaticData('global');
  if (!store.chats) store.chats = {};
  if (!store.chats[chatId]) store.chats[chatId] = [];
  return store.chats[chatId];
}
function pushMem(role, content) {
  const m = memory();
  m.push({ role, content: String(content || '').slice(0, 1500) });
  while (m.length > 12) m.shift();
}

const CLIENT_SYSTEM = `Você é o Assistente do Conecta King no Telegram.\nCordial, claro, PT-BR.\n\n${KB}\n\nRegras:\n- Responda o que o cliente perguntou (produto, planos, login, o que entrega).\n- NÃO invente códigos. NÃO diga que criou código.\n- Se pedirem humano/King/pessoa: confirme aviso e termine com ESCALATE:YES\n- Senão termine com ESCALATE:NO\n- Máx ~1200 caracteres.`;

let msg = '';
let escalate = /humano|falar com o king|atendente|pessoa real/i.test(text);

try {
  if (!openaiKey) {
    msg = `Olá, ${name}! Sou o Assistente do Conecta King.\nSite: https://www.conectaking.com.br\nLogin: https://www.conectaking.com.br/login\nPara humano: falar com o King.`;
  } else {
    const prefix = prev.hadVoice ? '[transcrito de áudio] ' : '';
    pushMem('user', prefix + text);
    const history = memory().slice(-10);
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/chat/completions',
      headers: { Authorization: 'Bearer ' + openaiKey, Accept: 'application/json', 'Content-Type': 'application/json' },
      body: { model, temperature: 0.45, max_tokens: 700, messages: [{ role: 'system', content: CLIENT_SYSTEM }, ...history] },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (r.statusCode >= 200 && r.statusCode < 300) {
      let content = String(r.body?.choices?.[0]?.message?.content || '').trim();
      if (/ESCALATE:\s*YES/i.test(content)) escalate = true;
      content = content.replace(/\n?ESCALATE:\s*(YES|NO)\s*$/i, '').trim();
      msg = content || `Olá, ${name}! Como posso ajudar?`;
      pushMem('assistant', msg);
    } else {
      msg = 'IA instável agora. Tente de novo ou diga "falar com o King".';
    }
  }
} catch (e) {
  msg = 'Falha temporária. Digite "falar com o King" para aviso humano.';
}

return [{ json: { ...prev, outMessage: msg, escalate: !!escalate } }];
